import json,sys,re,shlex
from pathlib import Path
R=Path(__file__).resolve().parents[1];sys.path.insert(0,str(R/'tools'))
from pre_route_endpoints import sha
roots=[R/'experiments/ethernet_native_cold_v1_2026-10-08',R/'experiments/ethernet_native_seed_v1_2026-10-08'];datasets=[];bindings={str(Path(__file__)):sha(Path(__file__))};commands=[]
for root in roots:
 p=root/'verification.json';v=json.loads(p.read_text());assert v['all_physical_endpoints_original_XML_arcs_and_node_NET_capacity_pass'] and v['original_native_FULL_check_pass'] and v['physical_connections']==41983 and all(sha(k)==x for k,x in v['bindings'].items());rp=root/'receipt.json';r=json.loads(rp.read_text());assert all(sha(k)==x for k,x in r['bindings'].items()) and all(sha(k)==x for k,x in r['files'].items());bindings.update({str(p):sha(p),str(rp):sha(rp)});datasets.append((r,v));text=(root/'native.log').read_text();commands.append(shlex.split(re.search(r'VPR was run with the following command-line:\n([^\n]+)',text)[1]))
assert commands[0]==commands[1]
for file in ['design.blif','design.net','design.place']:assert sha(roots[0]/file)==sha(roots[1]/file)
c,cv=datasets[0];s,sv=datasets[1];p=R/'experiments/ethernet_resident_v1_2026-10-08/receipt.json';e=json.loads(p.read_text());assert e['exit_code']==0 and all(sha(k)==x for k,x in e['bindings'].items());bindings[str(p)]=sha(p);charged=e['estimator_process_wall_seconds']+s['seed_preparation_seconds']+s['native_process_seconds'];assert s['retained_connections']+s['pending_connections']==s['required_connections']==41983
result=dict(bindings=bindings,physical_connections=41983,seed_connections=s['retained_connections'],pending_connections_still_routed=s['pending_connections'],cold_native_seconds=c['native_process_seconds'],seed_native_seconds=s['native_process_seconds'],seed_preparation_seconds=s['seed_preparation_seconds'],estimator_process_seconds=e['estimator_process_wall_seconds'],seed_measured_estimate_prepare_native_component_sum_seconds=charged,cold_iterations=cv['iterations'],seed_iterations=sv['iterations'],cold_wirelength=c['wirelength'],seed_wirelength=s['wirelength'],cold_diagnostic_cpd_ns=c['diagnostic_cpd_ns'],seed_diagnostic_cpd_ns=s['diagnostic_cpd_ns'],observed_native_only_time_gain=s['native_process_seconds']<c['native_process_seconds'],diagnostic_cpd_and_wire_nonincrease=s['diagnostic_cpd_ns']<=c['diagnostic_cpd_ns'] and s['wirelength']<=c['wirelength'],complete_workflow_time_measured=False,physical_timing_quality_gate_pass=False,canonical_reload_pass=False,unseen_family_generalization_pass=False,scope='Matched frozen single serial native cohort. Component sum is not complete continuous fullworkflow time; frontend/audits/canonical omitted and no statistical stable-speed claim. CPD is synthetic experimental async timing, not physical. All native endpoints/capacity verified, labels suitable only for scoped descriptive prediction evaluation.')
out=R/'experiments/ethernet_native_cohort_comparison_v1_2026-10-08';out.mkdir();(out/'comparison.json').write_text(json.dumps(result,indent=2)+'\n');print({k:v for k,v in result.items() if k not in ['bindings','scope']})
